### Code changes
```rust
fn handle_welcome(player: &mut MultiStreamPlayer, tts: &Arc<PiperTts>) {
    player.speak_sync("Hello!", tts);
    player.speak_sync("Checking for updates. Please wait.", tts);

    // ... update check ...

    player.speak_sync("Connecting to stations.", tts);
    let connected = player.connect_all(&channels::CHANNELS, Duration::from_secs(10));

    let msg = format!("Connected {} out of {} stations.", connected, channels::CHANNELS.len());
    player.speak_sync(&msg, tts);

    player.speak_sync("Change channel to start playing.", tts);
}
